import {voicePanel,voiceSelect} from './voice-client.js';
import {listeningPath} from './voice-config.js';
import {createSpeech} from './speech.js';
import {LIBRARY,PRACTICES,CONTENT_SOURCE} from './library-data.js';
import * as C from './core.js';
import {createCompanion} from './companion.js';
import {createMedia} from './media.js';
import {createShelf} from './shelf.js';
import {RESOURCES} from './resources-data.js';
import {createConnections} from './connections.js';
import {createBrowserAI} from './browser-ai.js';
import {LOCAL_SERVICE} from './runtime.js';
import {panel as pwaPanel} from './pwa.js';

export function createExtras({esc,head,button,icon,commit,toast,go,render,route,download,getState}) {
 let librarySection='resources';
 let category='全部',query='',selected=null,answers={},result=null,saved=false,started=0;
 let status=null,aiError='',aiTask='sentence',draft='',reply=null,busy=false,controller=null,pair='',saveDone=false,allowRemote=false;
 const speech=createSpeech({toast});
 const stopListening=()=>{speech.stop();document.querySelectorAll('audio[data-listening]').forEach(a=>a.pause());};
 const browserAI=LOCAL_SERVICE?null:createBrowserAI();
 if(browserAI)status=browserAI.status();
 const $=s=>document.querySelector(s);
 const kinds=['全部','阅读','听力','基础讲义','写作','口语'];
 const taskNames={sentence:'句子纠错',explain:'解释错题',translate:'中译英辅导',writing:'写作反馈',speaking:'口语文字稿反馈'};
 const refresh=()=>{if(['library','ai','companion','more'].includes(route()))render();};
 const companion=createCompanion({esc,button,toast,refresh:()=>{if(route()==='companion')render();},api,getStatus:()=>status,download});
 const connections=createConnections({esc,button,toast,refresh:()=>{if(route()==='ai')render();},getState,onModelChange:check});
 const media=createMedia({esc,button,toast,download});
 const shelf=createShelf({esc,head,button,toast,download,refresh:()=>{if(route()==='library'&&librarySection==='resources')render();}});
 const libraryTabs=()=>`<div class="workspace-tabs" role="group" aria-label="资料类型">${[['resources','官方与精选'],['original','原创练习'],['media','我的影音']].map(([id,name])=>button(name,'lib-section',`data-section="${id}" aria-pressed="${librarySection===id}"`,`filter ${librarySection===id?'active':''}`)).join('')}</div>`;
 function more(){return pwaPanel()+voicePanel()+head('A LITTLE MORE SUPPORT','让学习，更有方向','本地资料、可选 AI 辅导和你的学习备份。')+`<div class="library-grid">${[['companion','chat','聊天陪伴','随便聊聊 · 英语小剧场 · 猜词小游戏'],['recall','refresh','记忆巩固','隔天盲测 · 易混词对照 · 提示依赖记录'],['methods','headphones','学习方法','逐句精听 · 中译英小阶梯 · 错因复习'],['practice','target','今日专项','听写 · 句型变换 · 单词四维记录'],['library','book','本地资料库',`${LIBRARY.length} 份原创内容 · ${RESOURCES.length} 个精选入口 · 私人影音`],['ai','spark','AI 辅导与设置','句子纠错 · 写作反馈 · AI 连接设置'],['data','shield','数据与设置','导出、导入与阶段目标']].map(([id,i,title,desc])=>`<a class="library-card glass" href="#${id}">${icon(i)}<h2>${title}</h2><p>${desc}</p><span class="text-btn">打开 ${icon('arrow')}</span></a>`).join('')}</div>`;}
 function library(){
  if(librarySection==='resources')return libraryTabs()+`<div class="actions">${button(icon('headphones')+' 直接听一段 · 基础听力','lib-open','data-id="l01"','btn secondary')}</div>`+shelf.page();
  if(librarySection==='media')return libraryTabs()+media.page();
  const item=LIBRARY.find(x=>x.id===selected);if(item)return libraryTabs()+detail(item);
  const list=LIBRARY.filter(x=>(category==='全部'||x.kind===category)&&`${x.title} ${x.level} ${x.glossary||''}`.toLowerCase().includes(query.toLowerCase()));
  return libraryTabs()+head('YOUR OFFLINE LEARNING SHELF','今天，读一点新的','资料随项目保存在本地。先选一份短练习，再把收获留下。')+`<div class="library-hero glass"><div><span class="pill blue">${LIBRARY.length} 份本地资料 · 50 道听读题</span><h2>从基础，学会表达。</h2><p>6 篇阅读 · 4 份可播放听力 · 8 份基础讲义<br>6 个写作任务 · 8 组口语话题</p></div><div class="library-recommend"><small>今天可以从这里开始</small>${button('读一篇：安静的图书馆','lib-open','data-id="r01"','btn secondary')}${button('学一课：否定句','lib-open','data-id="n01"','text-btn')}</div></div><div class="library-tools"><div class="filters">${kinds.map(k=>button(k,'lib-filter',`data-kind="${k}" aria-pressed="${category===k}"`,`filter ${category===k?'active':''}`)).join('')}</div><form id="library-search" class="search-form"><label class="sr-only" for="library-query">搜索本地资料</label><input id="library-query" name="query" maxlength="100" value="${esc(query)}" placeholder="搜索标题、难度或词语"><button class="btn secondary" type="submit">搜索</button></form></div><p class="caption">${CONTENT_SOURCE}。难度标签为编写时的粗略定位，未经过标准化测评。</p><div class="library-grid">${list.map(x=>`<article class="library-card glass"><div class="record-top"><span class="pill">${x.kind}</span><small>${x.level} · 约 ${x.minutes} 分钟</small></div><h2>${esc(x.title)}</h2><p>${x.questions?`${x.questions.length} 道题 · 即时解析 · 错题收录`:'分步提示 · 可复制到 AI 辅导'}</p>${button('打开学习 '+icon('arrow'),'lib-open',`data-id="${x.id}"`,'text-btn')}</article>`).join('')||'<p>没有找到匹配内容，试试更短的关键词。</p>'}</div><p class="caption">想在其他工具阅读？${button('下载完整本地资料 JSON','lib-download','','link-button')}</p>`;
 }
 function detail(item){
  const listening=item.kind==='听力';
  const passage=`<div class="passage">${item.text?.split('\n\n').map(p=>`<p lang="en">${esc(p)}</p>`).join('')||''}</div>`;
  return `<div class="exercise-toolbar">${button(icon('back')+' 返回资料库','lib-back','','text-btn')}<span>${item.kind} · ${item.level}</span></div>`+head('ONE SMALL CHAPTER',esc(item.title),CONTENT_SOURCE)+
   (item.questions?`<div class="library-practice"><section class="panel glass reading-material"><h2>${listening?'先听一遍，再试着回答':'阅读材料'}</h2>${listening?`<div class="listening-player"><p class="notice">内置合成英语音频 · 原创基础练习，非真人录音、非雅思真题。无需 AI 或系统语音；首次缓存完成后可离线播放。</p>${voiceSelect(true)}<audio data-listening="${esc(item.id)}" controls preload="metadata" aria-label="${esc(item.title)} 听力音频" src="${listeningPath(item.id)}"></audio><label class="listening-speed">播放速度 <select data-listening-rate><option value="0.75">0.75 倍 · 慢一点</option><option value="1" selected>1 倍 · 正常</option><option value="1.25">1.25 倍</option></select></label><p class="caption" role="status">点播放键即可听，也可以暂停、拖动进度条或重播。</p></div><details class="speech-controls"><summary>改用设备朗读</summary><p class="caption">设备英语语音 · 部分声音需联网，可能由系统语音服务处理。</p><div class="actions">${button(icon('volume')+' 设备朗读','lib-play')}${button('停止','lib-stop','','btn ghost')}</div><p class="caption" data-speech-status role="status"></p></details><details class="transcript"><summary>查看听力文本</summary>${passage}</details>`:passage}<div class="notice">词语提示：${esc(item.glossary)}</div></section><section class="panel glass"><h2>${result?`本次答对 ${result.correct} / ${item.questions.length} 题`:'试着找出答案'}</h2><form id="library-quiz"><div class="quiz-list">${item.questions.map((q,i)=>`<fieldset class="quiz-question"><legend>${i+1}. ${esc(q.prompt)}</legend>${q.options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" ${answers[i]===j?'checked':''} ${result?'disabled':''} required><span>${esc(o)}</span></label>`).join('')}${result?`<div class="feedback ${answers[i]===q.answer?'':'wrong'}"><strong>${answers[i]===q.answer?'✓ 答对了':'再留意一下'} · ${esc(q.options[q.answer])}</strong><p>${esc(q.explanation)}</p></div>`:''}</fieldset>`).join('')}</div>${result?`<p class="notice">这是 ${item.questions.length} 题的原创短练习，不能换算真实 IELTS 分数。错误已进入${item.kind}错题本。</p><div class="field"><label for="practice-minutes">实际练习用时（分钟，可修改）</label><input id="practice-minutes" type="number" min="1" max="1440" value="${result?.minutes||Math.max(1,Math.round((Date.now()-started)/60000))}" ${saved?'disabled':''}></div>${button(saved?'已记入雅思进度':'保存本次正确题数','lib-save',saved?'disabled':'')}${button('重新练习','lib-restart','','btn ghost')}`:'<button class="btn" type="submit">检查答案并查看解析</button>'}</form></section></div>`:
   `<article class="panel glass lesson"><span class="pill blue">约 ${item.minutes} 分钟</span>${item.body.map((p,i)=>`<div class="lesson-step"><span>${String(i+1).padStart(2,'0')}</span><p>${esc(p)}</p></div>`).join('')}<div class="actions">${button('带着这份材料问 AI','lib-ai','data-id="'+item.id+'"')}${button('去记录练习反馈','lib-record','','btn secondary')}</div><p class="caption">阅读讲义不会自动计入完成；实际练习后，请记录自己的用时和收获。</p></article>`);
 }
 function companionPage(){
  if(browserAI)status=browserAI.status();
  const configured=status?.provider==='ollama'?status.status==='ready':!!status?.keyConfigured;
  const summary=configured?`当前模型：${status.model||'已配置模型'}`:browserAI?'先连接一个模型，就可以开始聊天。':'使用已有本地模型或 API，先检查连接。';
  return `<div class="companion-room"><section class="companion-connection glass" aria-label="聊天连接状态"><div><span class="pill">${configured?'使用已有连接':'等待连接模型'}</span><p>${esc(summary)}</p><small>与 AI 辅导共用连接设置。</small></div><div class="actions"><a href="#ai" class="btn secondary">连接设置</a>${LOCAL_SERVICE?button('检查连接','ai-refresh','','btn ghost'):''}</div></section>${aiError?`<p class="notice warm" role="alert">${esc(aiError)}</p>`:''}${companion.page({standalone:true})}</div>`;
 }
 function aiPage(){
  if(browserAI)status=browserAI.status();

  return head('A PATIENT ENGLISH TUTOR','把不懂的，一点点弄懂',LOCAL_SERVICE?'在这里连接模型，获得具体练习的反馈。':'在手机连接你已有的 API，练习英语并获得反馈。无需电脑开机；需要联网，服务商可能按用量计费。')+`<section class="companion-door glass"><div><h2>想轻松聊一会儿？</h2><p>聊天陪伴有自己的小空间了，四种玩法都在那里。</p></div><a href="#companion" class="btn secondary">打开聊天陪伴 ↗</a></section>`+connections.page()+(browserAI?browserSettings():'')+`<div id="ai-error" class="notice warm" role="alert" ${aiError?'':'hidden'}>${esc(aiError)}</div><div class="ai-status glass"><div>${icon('spark')}<div><strong>${status?.status==='ready'?'本地模型已就绪':status?.provider==='chatgpt'?'ChatGPT · 本机授权':status?.provider==='compatible'?(status.keyConfigured?'已有 API · '+(status.browser?'手机直连':'电脑中转'):'等待填写 API'):status?'本地 AI 待连接':'尚未检查连接'}</strong><p>${esc(status?.message||'先检查电脑上的 Ollama 服务。没有连接时，词汇、题库和记录仍可正常使用。')}</p></div></div>${button(LOCAL_SERVICE?'检查连接':'查看连接状态','ai-refresh','','btn secondary')}</div><div class="ai-layout"><section class="panel glass ai-tutor-panel"><h2>这次，想练什么？</h2><form id="ai-tutor"><div class="field"><label for="ai-task">辅导内容</label><select id="ai-task" name="task">${Object.entries(taskNames).map(([k,v])=>`<option value="${k}" ${aiTask===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="ai-text">题目、你的答案或英文草稿</label><textarea id="ai-text" name="text" rows="8" maxlength="12000" required placeholder="例如：我想表达“她昨天没去学校”。我写了 She didn't went to school yesterday. 为什么不对？">${esc(draft)}</textarea></div><p class="caption">${status?.browser&&!status.keyConfigured?'请先在顶部“手机 API 连接”填写设置。':['compatible','chatgpt'].includes(status?.provider)?`本次文本会发送到 ${esc(status.baseUrl)}，可能产生你已有服务的 API 用量。`:'本地模式连接本机 127.0.0.1:11434，只使用已下载的本地模型。'}不自动附带你的学习历史。</p>${['compatible','chatgpt'].includes(status?.provider)&&(!status.browser||status.keyConfigured)?`<label class="check-label"><input id="ai-remote" type="checkbox" ${allowRemote?'checked':''}>允许将本次填写的文本发送到此 API</label>`:''}<div class="actions"><button class="btn" type="submit" ${busy?'disabled':''}>${busy?'正在思考，请稍候…':'发送给 AI'}</button>${busy?button('取消请求','ai-cancel','','btn secondary'):button('填入一个纠错示例','ai-example','','text-btn')}</div></form>${reply?`<section class="ai-result" aria-live="polite"><span class="pill blue">AI 学习建议 · 非官方评分</span><p class="caption">${esc(reply.model)} · ${reply.provider==='ollama'?'本地 Ollama':'已配置 API'}</p><div class="ai-answer">${esc(reply.answer)}</div><p class="caption">模型可能出错，请与题目解析交叉核对。口语文字反馈不能判断发音和流利度。</p><div class="actions">${button('下载本次问答','ai-download','','btn secondary')}${['writing','speaking'].includes(reply.task)?`<div class="field"><label for="ai-practice-minutes">本次实际练习用时（分钟）</label><input id="ai-practice-minutes" type="number" min="1" max="1440" value="1" ${saveDone?'disabled':''}></div>`+button(saveDone?'已保存练习反馈':'保存为练习反馈','ai-save',saveDone?'disabled':'','btn secondary'):''}</div></section>`:'<div class="ai-placeholder"><span>✦</span><p>先自己试一句，再一起改进。</p><small>没有虚构回复，也不会生成官方雅思分数。</small></div>'}</section><aside ${LOCAL_SERVICE?'':'hidden'}><details class="panel glass ai-settings" ${!status||status.status!=='ready'?'open':''}><summary>连接与模型设置</summary><p class="caption">仅在电脑的 127.0.0.1 页面修改接口。手机使用配对码，本次服务重启后配对码会改变。</p>${status?.pairCode?`<details class="pair-details"><summary>查看本次手机配对码</summary><code>${esc(status.pairCode)}</code><p class="caption">仅给同一 Wi-Fi 下自己的设备使用。</p></details>`:''}<form id="ai-pair-form"><div class="field"><label for="ai-pair">手机配对码（仅本页内存保存）</label><input id="ai-pair" name="pair" maxlength="12" autocomplete="off" value="${esc(pair)}" placeholder="从电脑 AI 页面复制"></div><button class="btn ghost" type="submit">使用配对码连接</button></form>${!status||status.canConfigure?`<form id="ai-config-form"><div class="field"><label for="ai-provider">服务方式</label><select id="ai-provider" name="provider"><option value="ollama" ${['compatible','chatgpt'].includes(status?.provider)?'':'selected'}>Ollama · 免费本地</option><option value="chatgpt" ${status?.provider==='chatgpt'?'selected':''}>ChatGPT · 先在上方授权并选择模型</option><option value="compatible" ${status?.provider==='compatible'?'selected':''}>已有 OpenAI 兼容 API</option></select></div><div class="field"><label for="ai-model">模型名称</label><input id="ai-model" name="model" required maxlength="160" list="local-models" value="${esc(status?.model||'qwen3:4b')}"><datalist id="local-models">${(status?.models||[]).map(m=>`<option value="${esc(m)}">`).join('')}</datalist></div><div id="compatible-fields" ${status?.provider==='compatible'?'':'hidden'}><div class="field"><label for="ai-base">API Base URL（含 /v1，不含 /chat/completions）</label><input id="ai-base" name="baseUrl" type="url" placeholder="https://你的服务商/v1" value="${esc(status?.baseUrl||'')}"></div><div class="field"><label for="ai-key">API 密钥${status?.keyConfigured?'（已保存，留空沿用同一地址的密钥）':''}</label><input id="ai-key" name="apiKey" type="password" autocomplete="off" maxlength="4096"></div></div><p class="caption">配置保存在电脑 .local/ai.json，密钥不进入学习备份、前端或 GitHub。切回本地模式会移除已保存的 API 密钥。</p><button class="btn secondary" type="submit" ${busy?'disabled':''}>保存连接设置</button></form>`:''}</details><section class="panel glass setup-guide"><h2>第一次使用本地 AI</h2><ol><li>从 <a href="https://ollama.com/download/windows" target="_blank" rel="noopener noreferrer">Ollama 官网</a>安装并启动 Ollama。</li><li>在电脑终端运行 <code>ollama pull qwen3:4b</code>，下载约 2.5 GB 的示例模型。可改用已下载的其他本地聊天模型。</li><li>回到这里检查连接，填写模型名称，保存后发送一句测试。</li></ol><p class="caption">不需要购买 API。下载模型需要网络和磁盘空间；速度取决于电脑性能。这里不会自动下载模型或启用云端模型。</p><p class="caption">静态托管只提供学习页面；AI 需要通过项目的 <code>node server.mjs</code> 本机服务运行。</p></section></aside></div>`;
 }
 async function api(path,body,signal){if(browserAI){if(path==='status')return browserAI.status();if(path==='tutor')return browserAI.request(body,signal);throw new Error('此操作仅用于电脑本机版。');}let res;try{res=await fetch('./api/ai/'+path,{method:body?'POST':'GET',headers:{'X-Yan-Client':'1',...(pair?{'X-Yan-Pair':pair}:{}),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),signal});}catch(error){if(error.name==='AbortError')throw error;throw new Error('无法连接项目本机服务。请通过启动脚本打开网页。');}const data=await res.json().catch(()=>{throw new Error('当前地址不提供 AI 接口，请用 node server.mjs 启动本机版。');});if(!res.ok)throw new Error(data.error||'请求未完成。');return data;}
 function browserSettings(){
  const s=browserAI.status();
  return `<details class="panel glass browser-api-settings" ${!s.keyConfigured?'open':''}><summary>手机 API 连接 · ${s.keyConfigured?'已配置，可修改':'点这里开始'}</summary><p class="body-copy">填入你已有的 OpenAI 兼容接口。手机直接向此地址发送请求，不经过项目作者的服务器，也不需要 Ollama。</p><form id="ai-browser-config"><div class="field"><label for="browser-api-base">API 地址</label><input id="browser-api-base" name="baseUrl" type="url" required maxlength="2048" placeholder="https://你的服务商/v1" value="${esc(s.baseUrl)}" autocomplete="off" spellcheck="false"><small>按服务商文档填写 Base URL；粘贴完整 /chat/completions 地址也可以。</small></div><div class="field"><label for="browser-api-model">模型名称</label><input id="browser-api-model" name="model" required maxlength="160" placeholder="填写你账号中可用的模型名" value="${esc(s.model)}" autocomplete="off" spellcheck="false"></div><div class="field"><label for="browser-api-key">API 密钥${s.keyConfigured?'（留空沿用同一地址的密钥）':''}</label><input id="browser-api-key" name="apiKey" type="password" maxlength="4096" autocomplete="off" spellcheck="false" autocapitalize="none"></div><label class="check-label"><input name="remember" type="checkbox" ${s.persistent?'checked':''}>在这台设备记住 API 设置和密钥</label><p class="caption">默认仅当前页面使用。勾选记住后，密钥未加密保存在此浏览器；仅在自己的设备使用。密钥不进入学习或聊天备份，也不会上传 GitHub。</p><div class="actions"><button class="btn" type="submit">保存 API 设置</button>${s.keyConfigured?button('移除 API 连接','ai-browser-forget','','btn ghost'):''}</div></form><p class="notice">保存后，可进入「聊天陪伴」说一句“你好”，或在下方发送一道练习。只有真实收到回复才算连接成功。</p><details><summary>遇到跨域或连接失败怎么办？</summary><p class="caption">接口需要支持浏览器跨域（CORS），允许来源 <code>https://maquebaixue-ui.github.io</code>、POST 方法及 Authorization / Content-Type 请求头。可询问你的 API 服务商；网页无法自行解除限制，也不会把密钥转发到公共代理。手机本地离线仍可背词与做题，AI 需要联网。</p></details><details><summary>也想用免费的本地模型？</summary><p class="caption">本地 Ollama 仍需要电脑运行项目，手机通过同一 Wi-Fi 配对使用。已有 API 直连不需要电脑。</p><a href="https://github.com/maquebaixue-ui/-yan-english-studio#免费本地-aiollama" target="_blank" rel="noopener noreferrer">查看本地模型说明 ↗</a></details></details>`;
 }
 async function check(){try{status=await api('status');aiError='';}catch(e){aiError=e.message;status=null;}refresh();}
 function open(id){stopListening();librarySection='original';selected=id;answers={};result=null;saved=false;started=Date.now();render();window.scrollTo(0,0);}
 function act(action,el){
  if(connections.act(action,el)||companion.act(action,el)||media.act(action,el)||shelf.act(action,el))return true;
  if(!action.startsWith('lib-')&&!action.startsWith('ai-'))return false;
  const item=LIBRARY.find(x=>x.id===selected);
  if(action==='lib-section'){media.pause();stopListening();librarySection=el.dataset.section;selected=null;render();window.scrollTo(0,0);}
  if(action==='ai-mode')go(el.dataset.mode==='companion'?'companion':'ai');
  if(action==='lib-open')open(el.dataset.id);
  if(action==='lib-back'){selected=null;stopListening();render();}
  if(action==='lib-filter'){category=el.dataset.kind;render();}
  if(action==='lib-restart')open(selected);
  if(action==='lib-download')download('YAN-original-learning-library.json',JSON.stringify({source:CONTENT_SOURCE,materials:LIBRARY},null,2));
  if(action==='lib-save'&&result&&!saved){const minutes=Number($('#practice-minutes')?.value);commit(s=>C.addRecord(s,{skill:item.kind,date:C.today(),title:item.title+'（原创短练习）',correct:result.correct,total:item.questions.length,minutes,feedback:'本地题目按答案核对；非官方真题。',nextAction:'回到错题本复习本次错题。'}));saved=true;result.minutes=minutes;render();toast('真实正确题数已记录。');}
  if(action==='lib-stop')stopListening();
  if(action==='lib-play'){document.querySelectorAll('audio').forEach(a=>a.pause());speech.speak(item.text,{rate:.85,device:true});}
  if(action==='lib-ai'){aiTask=item.kind==='写作'?'writing':item.kind==='口语'?'speaking':'explain';draft=item.title+'\n'+item.body.join('\n')+'\n\n我的答案：';reply=null;go('ai');}
  if(action==='lib-record')go('progress');
  if(action==='ai-refresh')check();
  if(action==='ai-browser-forget'&&browserAI){try{status=browserAI.forget();allowRemote=false;aiError='';refresh();toast('已移除 API 连接。');}catch(e){aiError=e.message;refresh();}}
  if(action==='ai-example'){aiTask='sentence';draft="我想表达：她昨天没去学校。\n我的答案：She didn't went to school yesterday.\n请解释错误，并给我一道同类练习。";refresh();}
  if(action==='ai-cancel')controller?.abort();
  if(action==='ai-download'&&reply)download('YAN-AI-feedback-'+C.today()+'.json',JSON.stringify(reply,null,2));
  if(action==='ai-save'&&reply&&!saveDone){commit(s=>C.addRecord(s,{skill:reply.task==='writing'?'写作':'口语',date:C.today(),title:'AI 辅导 · '+reply.input.slice(0,80),minutes:Number($('#ai-practice-minutes')?.value),feedback:('AI 建议（非官方评分） · '+reply.model+'\n'+reply.answer).slice(0,5000),nextAction:'核对建议，修改后再练习。'}));saveDone=true;refresh();toast('已保存为 AI 建议，随学习备份一起导出。');}
  return true;
 }
 async function submit(form,values){
  if(form.id.startsWith('chatgpt-'))return connections.submit(form,values);
  if(shelf.submit(form,values))return true;
  if(form.id.startsWith('chat-'))return companion.submit(form,values);
  if(!['library-search','library-quiz','ai-config-form','ai-tutor','ai-pair-form','ai-browser-config'].includes(form.id))return false;
  try{
   if(form.id==='library-search'){query=values.query;render();}
   if(form.id==='library-quiz'&&!result){const item=PRACTICES.find(x=>x.id===selected);const selectedAnswers=item.questions.map((q,i)=>Number(values['q'+i]));if(selectedAnswers.some((a,i)=>!Number.isInteger(a)||!item.questions[i].options[a]))throw new Error('请完成每道题再检查。');answers=Object.fromEntries(selectedAnswers.map((v,i)=>[i,v]));let correct=0;commit(s=>{item.questions.forEach((q,i)=>{if(answers[i]===q.answer)correct++;else C.mistake(s,{category:item.kind,prompt:item.title+' · '+q.prompt+'\n\n'+item.text,answer:q.options[q.answer],userAnswer:q.options[answers[i]],note:q.explanation});});C.ensureDay(s).activities++;});result={correct};render();toast(`本次答对 ${correct} / ${item.questions.length} 题。`);}
   if(form.id==='ai-browser-config'&&browserAI){status=browserAI.save(values);allowRemote=false;aiError='';refresh();toast('设置已保存，可以发送一句话试试。');}
   if(form.id==='ai-pair-form'){pair=values.pair.trim();await check();}
   if(form.id==='ai-config-form'){await api('config',values);$('#ai-key').value='';await check();toast('配置已保存在这台电脑。');}
   if(form.id==='ai-tutor'){
    if(busy)return true;draft=values.text;aiTask=values.task;allowRemote=!!$('#ai-remote')?.checked;
    if(!status){await check();if(!status)throw new Error(aiError||'请先检查连接。');}
    if(status.browser&&!status.keyConfigured)throw new Error('请先在顶部“手机 API 连接”填写地址、模型和密钥。');
    if(status.provider==='ollama'&&status.status!=='ready')throw new Error('本地模型尚未就绪，请按右侧步骤连接 Ollama。');
    if(status.provider!=='ollama'&&!allowRemote)throw new Error('请先勾选允许发送本次文本到已配置 API。');
    busy=true;aiError='';reply=null;saveDone=false;controller=new AbortController();const begin=Date.now(),requestTask=aiTask,requestText=draft;refresh();
    try{const output=await api('tutor',{task:requestTask,text:requestText,allowRemote},controller.signal);reply={...output,task:requestTask,input:requestText,date:C.today(),elapsed:Date.now()-begin};}catch(e){aiError=e.name==='AbortError'?'本次请求已取消。':e.message;}finally{busy=false;controller=null;allowRemote=false;refresh();}
   }
  }catch(e){if(form.id.startsWith('ai-')){aiError=e.message;if(form.id==='ai-browser-config'&&$('#ai-error')){$('#ai-error').textContent=aiError;$('#ai-error').hidden=false;}else refresh();}else toast(e.message);}
  return true;
 }
 function input(event){connections.input(event);companion.input(event);media.input(event);shelf.input(event);const el=event.target;if(el.id==='ai-text')draft=el.value;if(el.id==='ai-task')aiTask=el.value;if(el.id==='ai-provider')$('#compatible-fields').hidden=el.value!=='compatible';if(el.id==='ai-remote')allowRemote=el.checked;if(el.closest('#library-quiz')&&el.name.startsWith('q'))answers[Number(el.name.slice(1))]=Number(el.value);}
 function askMistake(m){aiTask='explain';draft=`题目：${m.prompt}\n我的答案：${m.userAnswer}\n参考答案：${m.answer}\n已有解析：${m.note}\n请解释关键错误。`;reply=null;go('ai');}
 function reset(){companion.reset();media.reset();selected=null;answers={};result=null;saved=false;controller?.abort();reply=null;draft='';saveDone=false;stopListening();}
 return {library,aiPage,companionPage,more,act,submit,input,askMistake,reset,leave:()=>{companion.leave();media.pause();stopListening();}};
}
